 const amenities=(spaceText(s,'amenities')||'').split(',').map(x=>x.trim()).filter(Boolean);
 const rates=[['Hour',s.rate_hour],['Day',s.rate_day],['Week',s.rate_week],['Month',s.rate_month]].filter(([,v])=>Number(v)>0);
